window.ENT141_INDEX=[{"pt": "Week 1", "l": "week-01.html#s0", "n": "Start here", "t": "Why do some people turn problems into ventures?", "x": "This course takes your team from a real social problem to an idea backed by evidence. Topics: Course Material · Course Assignments · Groups formation · What is Entrepreneurship? · Role of Entrepreneurs in the Society. CLO 1."}, {"pt": "Week 1", "l": "week-01.html#s1", "n": "Course material", "t": "Course material", "x": "One textbook and a few short readings. Each lecture page names its reading on the first scene."}, {"pt": "Week 1", "l": "week-01.html#s2", "n": "Course assignments", "t": "Course assignments", "x": "The project guide explains it one part at a time."}, {"pt": "Week 1", "l": "week-01.html#s3", "n": "What is entrepreneurship?", "t": "What is entrepreneurship?", "x": "An entrepreneur spots a problem worth solving and builds a venture to solve it, accepting risk to create value (Byers et al., 2019, Ch. 1)."}, {"pt": "Week 1", "l": "week-01.html#s4", "n": "Role in society", "t": "Role of entrepreneurs in the society", "x": "Entrepreneurs create jobs, new services and growth. Careem started in Dubai in July 2012; when Uber completed its $3.1 billion acquisition in January 2020, Careem reported more than one million employment opportunities created in the region."}, {"pt": "Week 1", "l": "week-01.html#s5", "n": "Groups formation", "t": "Activity · Form your team", "x": "No idea yet? Open the Toolkit."}, {"pt": "Week 1", "l": "week-01.html#s6", "n": "Think about it", "t": "Think about it", "x": "Discuss with your team, then reveal one view. There is no single right answer. Next week: read Byers et al (2019) Ch. 8 and Lubberink et al (2017)."}, {"pt": "Week 2", "l": "week-02.html#s0", "n": "Start here", "t": "Is every new idea an innovation?", "x": "An idea becomes an innovation only when people use it and it creates value. Topics: What is Innovative Thinking · Innovation V/S Invention · What is Creativity? · How is creativity linked to innovative thinking and entrepreneurship? CLO 2."}, {"pt": "Week 2", "l": "week-02.html#s1", "n": "Innovative thinking", "t": "What is innovative thinking?", "x": "Innovative thinking looks for a new way to create value: a product, a process, a business model or a social change. Lubberink et al. (2017) study how social entrepreneurs develop innovations for society."}, {"pt": "Week 2", "l": "week-02.html#s2", "n": "Innovation vs invention", "t": "Innovation V/S invention", "x": "An invention is a new idea or device; an innovation is one that people adopt and that creates value. Greenhouse climate control already worked in Arizona and Norway; Pure Harvest adapted it to the UAE, which imports nearly 80% of its food."}, {"pt": "Week 2", "l": "week-02.html#s3", "n": "What is creativity?", "t": "What is creativity?", "x": "Creativity is producing ideas that are both new and useful (Byers et al., 2019, Ch. 8). It grows with practice and is easily lost when every idea is judged too early."}, {"pt": "Week 2", "l": "week-02.html#s4", "n": "Creativity → entrepreneurship", "t": "How is creativity linked to innovative thinking and entrepreneurship?", "x": "Creativity supplies the ideas, innovative thinking turns them into value, and entrepreneurship builds the venture that delivers it."}, {"pt": "Week 2", "l": "week-02.html#s5", "n": "Idea burst", "t": "Activity · Idea burst on your social need", "x": "As a team, list ideas for the social need you chose in Week 1. Quantity first, judgement later."}, {"pt": "Week 2", "l": "week-02.html#s6", "n": "Think about it", "t": "Think about it", "x": "Discuss with your team, then reveal one view. There is no single right answer. Next week: read Ray & Shaw (2022) Ch. 1 and Krzymowski (2020)."}, {"pt": "Week 3", "l": "week-03.html#s0", "n": "Start here", "t": "Can a venture be good for people, planet and profit?", "x": "Sustainability asks a venture to stay viable without harming people or the planet. Topics: The Triple Bottom-line Framework · United Nations Sustainable Development Goals · Understanding Sustainable Entrepreneurship · Sustainability in the UAE. CLO 1 · CLO 2 · CLO 4."}, {"pt": "Week 3", "l": "week-03.html#s1", "n": "Triple bottom line", "t": "The triple bottom-line framework", "x": "Elkington's triple bottom line (1994) judges a venture on three results: people, planet and profit. Score your team's first idea; each score needs something you can count."}, {"pt": "Week 3", "l": "week-03.html#s2", "n": "The SDGs", "t": "United Nations Sustainable Development Goals", "x": "In 2015 the UN adopted 17 goals and 169 targets for 2030. A strong project links to a target, such as 4.4 on skills for jobs, not only to a goal."}, {"pt": "Week 3", "l": "week-03.html#s3", "n": "Sustainable entrepreneurship", "t": "Understanding sustainable entrepreneurship", "x": "A sustainable entrepreneur earns revenue by solving an environmental or social problem. Enviroserve's Dubai plant (2019) can process 100,000 tonnes of waste a year, including 39,000 tonnes of e-waste, with a 96% recovery rate."}, {"pt": "Week 3", "l": "week-03.html#s4", "n": "Sustainability in the UAE", "t": "Sustainability in the UAE", "x": "The UAE links its national plans to the 2030 Agenda (Krzymowski, 2020). In October 2021 it became the first MENA country to commit to net zero by 2050."}, {"pt": "Week 3", "l": "week-03.html#s5", "n": "Your SDG", "t": "Activity · Link your social need to an SDG", "x": "Choose the main SDG for your team's social need, then write the target number in part 1 of your poster. Not sure it fits? Use the SDG check."}, {"pt": "Week 3", "l": "week-03.html#s6", "n": "Think about it", "t": "Think about it", "x": "Discuss with your team, then reveal one view. There is no single right answer. Next week: read Kummitha (2019)."}, {"pt": "Week 9", "l": "week-09.html#s0", "n": "Start here", "t": "How do you solve a problem you do not have yourself?", "x": "Design thinking starts with the people who have the problem, not with your idea. CLO 1 · CLO 3."}, {"pt": "Week 9", "l": "week-09.html#s1", "n": "What is design thinking?", "t": "Introduction to the design thinking process", "x": "Design thinking is a human-centred way to solve problems by understanding users, trying many ideas and testing them early. Kummitha (2019) shows the role of engaging users when social organisations innovate."}, {"pt": "Week 9", "l": "week-09.html#s2", "n": "The five steps", "t": "The five steps of the DTP", "x": "The Stanford d.school uses five steps, repeated in loops. Weeks 5 to 9 take one step at a time."}, {"pt": "Week 9", "l": "week-09.html#s3", "n": "Case: Embrace", "t": "Case · Embrace infant warmer", "x": "Stanford students designed a low-cost infant warmer (2007). Watching rural families in Nepal changed the design: they added a model for use at home."}, {"pt": "Week 9", "l": "week-09.html#s4", "n": "Innovative mindset", "t": "Building an innovative mindset", "x": "The d.school names seven mindsets behind design thinking. Pick the one your team needs most this term."}, {"pt": "Week 9", "l": "week-09.html#s6", "n": "Think about it", "t": "Think about it", "x": "Discuss with your team, then reveal one view. There is no single right answer. Next week: read the Stanford d.school Process Guide, Empathize mode."}, {"pt": "Week 4", "l": "week-04.html#s0", "n": "Start here", "t": "What does your user really do, think and feel?", "x": "Empathy is the base of the poster: interviews, an empathy map and a journey map. Topics: Empathy Map · Journey Map. CLO 3."}, {"pt": "Week 4", "l": "week-04.html#s1", "n": "What is empathy?", "t": "What is empathy?", "x": "Empathy is understanding a person's experience from their point of view. The d.school asks you to observe, engage and immerse: watch, talk and try it yourself."}, {"pt": "Week 4", "l": "week-04.html#s2", "n": "Interview for empathy", "t": "Interview for empathy", "x": "Ask about real past events, then ask why. Avoid questions that lead, sell your idea or end with yes or no. Fix each question below."}, {"pt": "Week 4", "l": "week-04.html#s3", "n": "Empathy map", "t": "Empathy map", "x": "An empathy map sorts what you learned into four parts: what the user says, thinks, does and feels. Gaps between says and does are where insights hide."}, {"pt": "Week 4", "l": "week-04.html#s4", "n": "Journey map", "t": "Journey map", "x": "A journey map follows the user step by step and tracks how they feel at each stage. The lowest point is usually the pain point worth solving."}, {"pt": "Week 4", "l": "week-04.html#s5", "n": "Plan your interviews", "t": "Activity · Plan your interviews", "x": "The poster rubric rewards many interviews with deep answers. Plan at least five, then add the best quotes to part 2 of your poster. Need questions? Use the question designer."}, {"pt": "Week 4", "l": "week-04.html#s6", "n": "Think about it", "t": "Think about it", "x": "Discuss with your team, then reveal one view. There is no single right answer. Next week: read Byers et al (2019) Ch. 2 and the d.school Process Guide, Define mode. Bring your interview notes."}, {"pt": "Week 5", "l": "week-05.html#s0", "n": "Start here", "t": "What exactly are we solving, and for whom?", "x": "Defining turns interview notes into one clear problem and a few “How might we…” questions. Topics: Primary Data Collection Methods · How Might We (HMW) Questions · Problem Definition & Sustainability. CLO 1 · CLO 3."}, {"pt": "Week 5", "l": "week-05.html#s1", "n": "Primary data", "t": "Primary data collection methods", "x": "Primary data is what your team collects first-hand; secondary data already exists, such as UN or government statistics. For the poster, interviews and observation come first; for secondary data, use the open data finder."}, {"pt": "Week 5", "l": "week-05.html#s2", "n": "From notes to insight", "t": "From notes to insight", "x": "An insight is a surprising reason behind what users do. Move from what you saw and heard to what it means."}, {"pt": "Week 5", "l": "week-05.html#s3", "n": "How might we", "t": "How Might We (HMW) questions", "x": "A point of view joins user, need and insight. A “How might we…” question turns it into an open challenge: not so broad that anything fits, not so narrow that it names the solution."}, {"pt": "Week 5", "l": "week-05.html#s4", "n": "Problem and sustainability", "t": "Problem definition & sustainability", "x": "Check your problem against the triple bottom line from Week 3: who suffers (people), what is wasted or harmed (planet), and what it costs (profit)."}, {"pt": "Week 5", "l": "week-05.html#s5", "n": "Define your problem", "t": "Activity · Define your problem", "x": "Use your interview notes. Write the point of view, then three HMW questions; the checks flag the common mistakes. Copy the best into part 5 of your poster."}, {"pt": "Week 5", "l": "week-05.html#s6", "n": "Think about it", "t": "Think about it", "x": "Discuss with your team, then reveal one view. There is no single right answer. Next week: read Byers et al (2019) Ch. 2 and 3. Bring your best HMW question."}];
